	mask._off = true;
	mask.graphics.p("AnKCKQhFgBAAg7IAAiaQAAg9BFAAIKnAAIACAAIAFAAIARACIAFACQgoALAAAuIAACUQAAAzAxAIIgGACIggAFgAGbg8IB1BCIh1A8Qgfg4AfhGg");
	mask.setTransform(53.8,14.8);

